import re
import pandas as pd
from datetime import datetime

_NUM_RE = re.compile(r'^[+-]?\d+(\.\d{1,2})?$')
_DATE_RE = re.compile(r'^\d{4}-\d{2}-\d{2}$')


def _is_null(v):
    if v is None:
        return True
    try:
        if isinstance(v, float) and pd.isna(v):
            return True
    except Exception:
        pass
    if pd.isna(v):
        return True
    return False


def run(inputs: dict) -> dict:
    df = inputs["raw_payments"]

    valid_rows = []
    reject_rows = []

    # intermediate storage for rows that passed R1-R5, to apply R6 later
    passed = []  # list of dicts with row_num, payment_id_trim, account_id, amount, currency, pay_date

    for _, row in df.iterrows():
        row_num = row["row_num"]
        payment_id = row["payment_id"]
        account_id = row["account_id"]
        amount_txt = row["amount_txt"]
        currency = row["currency"]
        pay_date_txt = row["pay_date_txt"]

        # R1 MISSING_ID
        if _is_null(payment_id):
            reject_rows.append((row_num, "MISSING_ID"))
            continue
        pid_trim = str(payment_id).strip()
        if pid_trim == "":
            reject_rows.append((row_num, "MISSING_ID"))
            continue

        # R2 BAD_AMOUNT
        if _is_null(amount_txt):
            reject_rows.append((row_num, "BAD_AMOUNT"))
            continue
        amt_trim = str(amount_txt).strip()
        if not _NUM_RE.match(amt_trim):
            reject_rows.append((row_num, "BAD_AMOUNT"))
            continue
        parsed_amount = float(amt_trim)

        # R3 NON_POSITIVE
        if parsed_amount <= 0:
            reject_rows.append((row_num, "NON_POSITIVE"))
            continue

        # R4 BAD_CURRENCY
        if _is_null(currency):
            reject_rows.append((row_num, "BAD_CURRENCY"))
            continue
        cur_trim = str(currency).strip().upper()
        if cur_trim not in ("USD", "EUR", "GBP"):
            reject_rows.append((row_num, "BAD_CURRENCY"))
            continue

        # R5 BAD_DATE
        if _is_null(pay_date_txt):
            reject_rows.append((row_num, "BAD_DATE"))
            continue
        date_trim = str(pay_date_txt).strip()
        if not _DATE_RE.match(date_trim):
            reject_rows.append((row_num, "BAD_DATE"))
            continue
        try:
            parsed_date = datetime.strptime(date_trim, "%Y-%m-%d").date()
        except ValueError:
            reject_rows.append((row_num, "BAD_DATE"))
            continue

        passed.append({
            "row_num": row_num,
            "payment_id": pid_trim,
            "account_id": account_id,
            "amount": parsed_amount,
            "currency": cur_trim,
            "pay_date": parsed_date,
        })

    # R6 DUPLICATE
    groups = {}
    for item in passed:
        groups.setdefault(item["payment_id"], []).append(item)

    for pid, items in groups.items():
        if len(items) == 1:
            valid_rows.append(items[0])
        else:
            items_sorted = sorted(items, key=lambda x: x["row_num"])
            winner = items_sorted[0]
            valid_rows.append(winner)
            for loser in items_sorted[1:]:
                reject_rows.append((loser["row_num"], "DUPLICATE"))

    valid_df = pd.DataFrame(valid_rows, columns=[
        "row_num", "payment_id", "account_id", "amount", "currency", "pay_date"
    ])
    if not valid_df.empty:
        valid_df = valid_df.sort_values("row_num").reset_index(drop=True)
        valid_df = valid_df[["payment_id", "account_id", "amount", "currency", "pay_date"]]
    else:
        valid_df = pd.DataFrame(columns=["payment_id", "account_id", "amount", "currency", "pay_date"])

    reject_df = pd.DataFrame(reject_rows, columns=["row_num", "reject_reason"])
    if not reject_df.empty:
        reject_df = reject_df.sort_values("row_num").reset_index(drop=True)

    return {
        "valid_payments": valid_df,
        "payment_rejects": reject_df,
    }
